CREATE TABLE IF NOT EXISTS people (id SERIAL PRIMARY KEY, name TEXT NOT NULL, initials TEXT NOT NULL, color TEXT NOT NULL DEFAULT '#dcebdd', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS groups (id SERIAL PRIMARY KEY, name TEXT NOT NULL, icon TEXT NOT NULL DEFAULT 'users', color TEXT NOT NULL DEFAULT '#dcebdd', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS expenses (id SERIAL PRIMARY KEY, group_id INTEGER NOT NULL REFERENCES groups(id) ON DELETE CASCADE, title TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount > 0), paid_by INTEGER NOT NULL REFERENCES people(id), category TEXT NOT NULL DEFAULT 'Other', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS splits (id SERIAL PRIMARY KEY, expense_id INTEGER NOT NULL REFERENCES expenses(id) ON DELETE CASCADE, person_id INTEGER NOT NULL REFERENCES people(id), amount NUMERIC(12,2) NOT NULL CHECK(amount >= 0));
CREATE TABLE IF NOT EXISTS settlements (id SERIAL PRIMARY KEY, payer_id INTEGER NOT NULL REFERENCES people(id), payee_id INTEGER NOT NULL REFERENCES people(id), amount NUMERIC(12,2) NOT NULL CHECK(amount > 0), note TEXT NOT NULL DEFAULT 'Settlement', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
